if (session?.authenticated && !closing && !closeError && !failure)
    return (
      <AppearanceProvider key={session.username}>
        <div className="access-recovery" hidden={!csrfExpired}>
          <p role={csrfExpired ? "alert" : undefined}>
            {recoveryFailed ? "No hemos podido renovar el acceso. " : ""}La
            protección de tu sesión necesita renovarse. Recupera el acceso y
            decide si vuelves a enviar los cambios.
          </p>
          <button onClick={() => refresh(true)}>Recuperar acceso</button>
        </div>
        <App
          username={session.username}
          sessionControls={
            <button className="session-logout" onClick={logout}>
              Cerrar sesión
            </button>
          }
        />
      </AppearanceProvider>
    );

function isPrivateRoute(path: string, search: string) {
  if (path === "/proyectos") {
    const query = new URLSearchParams(search);
    return (
      !search ||
      (query.size === 1 && query.has("cursor") && Boolean(query.get("cursor")))
    );
  }
  return (
    !search &&
    (path === "/" ||
      path === "/disponibilidad" ||
      path === "/apariencia" ||
      path === "/exportacion" ||
      path === "/proyectos/nuevo" ||
      /^\/proyectos\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(?:\/editar|\/tareas\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(?:\/sesiones\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})?)?$/i.test(
        path,
      ))
  );
}
